def _escape(value):
    """Apply RFC 4180 minimal quoting and quote doubling to one field."""
    if any(ch in value for ch in (",", '"', "\r", "\n")):
        return '"' + value.replace('"', '""') + '"'
    return value


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header."""
    cols = []
    seen = set()
    for col in columns:
        if not isinstance(col, str):
            raise ValueError("column names must be strings")
        if col in seen:
            raise ValueError("duplicate column name: %r" % (col,))
        seen.add(col)
        cols.append(col)

    def record(values):
        return ",".join(_escape(v) for v in values) + "\r\n"

    out = [record(cols)]
    for row in rows:
        fields = []
        for col in cols:
            value = row.get(col)
            fields.append("" if value is None else str(value))
        out.append(record(fields))
    return "".join(out)
